package com.hbm.machine.reactor.icf;
import java.util.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.world.flag.FeatureFlags;
import net.minecraft.world.inventory.MenuType;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.neoforged.bus.api.IEventBus;

import net.neoforged.neoforge.capabilities.*;
import net.neoforged.neoforge.items.wrapper.*;
import net.neoforged.neoforge.network.IContainerFactory;
import net.neoforged.neoforge.registries.*;
public final class IcfReactorContent{
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<IcfReactorBlock> REACTOR=BLOCKS.register("icf",IcfReactorBlock::new);public static final DeferredBlock<IcfStructBlock> STRUCT=BLOCKS.register("struct_icf_core",IcfStructBlock::new);public static final DeferredBlock<IcfLaserBlock> LASER=BLOCKS.register("icf_controller",IcfLaserBlock::new);public static final DeferredBlock<IcfFormedBlock> FORMED=BLOCKS.register("icf_block",IcfFormedBlock::new);public static final DeferredBlock<IcfMaterialBlock> COMPONENT=BLOCKS.register("icf_component",()->new IcfMaterialBlock(false)),LASER_COMPONENT=BLOCKS.register("icf_laser_component",()->new IcfMaterialBlock(true));
 public static final DeferredItem<BlockItem> REACTOR_ITEM=ITEMS.registerSimpleBlockItem(REACTOR),STRUCT_ITEM=ITEMS.registerSimpleBlockItem(STRUCT),LASER_ITEM=ITEMS.registerSimpleBlockItem(LASER),FORMED_ITEM=ITEMS.registerSimpleBlockItem(FORMED);public static final DeferredItem<IcfMaterialItem> COMPONENT_ITEM=ITEMS.register("icf_component",()->new IcfMaterialItem(COMPONENT.get())),LASER_COMPONENT_ITEM=ITEMS.register("icf_laser_component",()->new IcfMaterialItem(LASER_COMPONENT.get()));
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<IcfReactorEntity>> REACTOR_ENTITY=ENTITIES.register("icf",()->BlockEntityType.Builder.of(IcfReactorEntity::new,REACTOR.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<IcfReactorPort>> REACTOR_PORT=ENTITIES.register("icf_port",()->BlockEntityType.Builder.of(IcfReactorPort::new,REACTOR.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<IcfStructEntity>> STRUCT_ENTITY=ENTITIES.register("icf_structure",()->BlockEntityType.Builder.of(IcfStructEntity::new,STRUCT.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<IcfLaserEntity>> LASER_ENTITY=ENTITIES.register("icf_controller",()->BlockEntityType.Builder.of(IcfLaserEntity::new,LASER.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<IcfFormedEntity>> FORMED_ENTITY=ENTITIES.register("icf_block",()->BlockEntityType.Builder.of(IcfFormedEntity::new,FORMED.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<IcfReactorMenu>> MENU=MENUS.register("icf",()->new MenuType<>((IContainerFactory<IcfReactorMenu>)IcfReactorMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(IcfReactorContent::capabilities);}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,REACTOR_ENTITY.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,REACTOR_PORT.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));}
 public static List<ItemStack> materialStacks(){var list=new ArrayList<ItemStack>();for(int i=0;i<5;i++)list.add(COMPONENT.get().stack(i,1));for(int i=0;i<6;i++)list.add(LASER_COMPONENT.get().stack(i,1));return list;}public static List<ItemStack> creativeStacks(String tab){if(!tab.equals("machine"))return List.of();var list=new ArrayList<ItemStack>(materialStacks());list.add(new ItemStack(REACTOR_ITEM.get()));list.add(new ItemStack(STRUCT_ITEM.get()));list.add(new ItemStack(LASER_ITEM.get()));return list;}private IcfReactorContent(){}
}
